#include <iostream>
#include <vector>

int main()
{
    std::vector<int> values(4'000'000);

    for (std::size_t i{ 0 }; i < values.size(); ++i)
    {
        values[i] = static_cast<int>(i) * 2;
    }
    std::cout << values[3'999'999] << '\n';
    return 0;
}
